from datetime import date, timedelta
from typing import List, Optional

class LeaveTracker:
    def __init__(self, days_per_year: int = 26, holidays: Optional[List[date]] = None) -> None:
        self.days_per_year = days_per_year
        self.holidays = holidays or []
        # Track used leave days per employee per year
        self.used_days = {}  # {employee: {year: days_used}}

    def _is_weekend(self, d: date) -> bool:
        return d.weekday() >= 5  # Saturday=5, Sunday=6

    def _is_holiday(self, d: date) -> bool:
        return d in self.holidays

    def _is_leave_day(self, d: date) -> bool:
        return not (self._is_weekend(d) or self._is_holiday(d))

    def _count_leave_days(self, start: date, end: date) -> int:
        """Count business days (excluding weekends and holidays) between start and end (inclusive)."""
        if start > end:
            return 0

        count = 0
        current = start
        while current <= end:
            if self._is_leave_day(current):
                count += 1
            current += timedelta(days=1)
        return count

    def request(self, employee: str, start: date, end: date, today: date) -> int:
        """Request leave from start to end (inclusive); returns the number of leave days used."""
        # Requirement 2: end date before start date
        if end < start:
            raise ValueError("End date cannot be before start date")

        # Requirement 1: request made less than 3 days before start date
        if (start - today).days < 3:
            raise ValueError("Leave request must be made at least 3 days before start date")

        # Calculate leave days needed (excluding weekends and holidays)
        leave_days_needed = self._count_leave_days(start, end)

        # Get the year for this request
        year = start.year

        # Get current used days for this employee and year
        if employee not in self.used_days:
            self.used_days[employee] = {}
        if year not in self.used_days[employee]:
            self.used_days[employee][year] = 0

        used_so_far = self.used_days[employee][year]

        # Requirement 4: check if enough remaining days
        if leave_days_needed > (self.days_per_year - used_so_far):
            raise ValueError("Not enough remaining leave days")

        # Record the used days
        self.used_days[employee][year] += leave_days_needed
        return leave_days_needed

    def remaining(self, employee: str, year: int) -> int:
        """Return remaining leave days for employee in given year."""
        if employee not in self.used_days or year not in self.used_days[employee]:
            return self.days_per_year
        return self.days_per_year - self.used_days[employee][year]
